SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [VMaster].[DELETE_VIDEOGRAPHER_MASTER]
(
	@VIDEOGRAPHER_ID INT
)

AS
BEGIN

SET NOCOUNT ON

IF NOT EXISTS (SELECT 'X' 
FROM [VMaster].[TBL_VIDEOGRAPHER_MASTER] 
WHERE VIDEOGRAPHER_ID=@VIDEOGRAPHER_ID)
BEGIN
	SELECT 'Error','RECORD NOT EXISTS SUCCESSFULL',@VIDEOGRAPHER_ID
END

ELSE
BEGIN

DELETE [VMaster].[TBL_VIDEOGRAPHER_MASTER]
WHERE VIDEOGRAPHER_ID=@VIDEOGRAPHER_ID

SELECT '','RECORD DELETED SUCCESSFULL',@VIDEOGRAPHER_ID

END

END

GO
