CREATE PROCEDURE [VMaster].[SAVE_ANIMAL_HUNTING_CHARGES_MASTER_HDR]
(
    @ANIMAL_HUNT_CHARGE_ID INT,
    @COMPANY_ID INT,
    @EFFECTIVE_YEAR VARCHAR(10),
    @ISSUING_AUTHORITY VARCHAR(50),
    @APPROVAL_REFERENCE_NO VARCHAR(50),
    @APPROVAL_DATE DATETIME,
    @EFFECTIVE_FROM DATETIME,
    @EFFECTIVE_TO DATETIME,
    @CURRENCY_ID INT,
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
SET NOCOUNT ON

IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR] WHERE COMPANY_ID=@COMPANY_ID   AND EFFECTIVE_YEAR=@EFFECTIVE_YEAR)
BEGIN
    SELECT 'ERROR','RECORD ALREADY EXISTS','0'
END

ELSE BEGIN
INSERT INTO [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR]
(
    COMPANY_ID,
    EFFECTIVE_YEAR,
    ISSUING_AUTHORITY,
    APPROVAL_REFERENCE_NO,
    APPROVAL_DATE,
    EFFECTIVE_FROM,
    EFFECTIVE_TO,
    CURRENCY_ID,
    SECTION_HEAD_RESPONSE_PERSON,
    SECTION_HEAD_RESPONSE_DATE,
    SECTION_HEAD_RESPONSE_STATUS,
    SECTION_HEAD_RESPONSE_REMARKS,
    RESPONSE_1_PERSON,
    RESPONSE_1_DATE,
    RESPONSE_1_STATUS,
    RESPONSE_1_REMARKS,
    RESPONSE_2_PERSON,
    RESPONSE_2_DATE,
    RESPONSE_2_STATUS,
    RESPONSE_2_REMARKS,
    FINAL_RESPONSE_PERSON,
    FINAL_RESPONSE_DATE,
    FINAL_RESPONSE_STATUS,
    FINAL_RESPONSE_REMARKS,
    REMARKS,
    STATUS_MASTER,
    CREATED_BY,
    CREATED_DATE,
    CREATED_MAC_ADDRESS,
    MODIFIED_BY,
    MODIFIED_DATE,
    MODIFIED_MAC_ADDRESS
)
VALUES
(
    @COMPANY_ID,
    @EFFECTIVE_YEAR,
    @ISSUING_AUTHORITY,
    @APPROVAL_REFERENCE_NO,
    @APPROVAL_DATE,
    @EFFECTIVE_FROM,
    @EFFECTIVE_TO,
    @CURRENCY_ID,

    NULL,NULL,NULL,NULL,
    NULL,NULL,NULL,NULL,
    NULL,NULL,NULL,NULL,
    NULL,NULL,NULL,NULL,

    @REMARKS,
    @STATUS_MASTER,
    @USER,
    GETDATE(),
    @MAC_ADDRESS,
    @USER,
    GETDATE(),
    @MAC_ADDRESS
)

SELECT @ANIMAL_HUNT_CHARGE_ID=MAX(ANIMAL_HUNT_CHARGE_ID) FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR]

SELECT '','DATA SAVED SUCCESSFULLY',@ANIMAL_HUNT_CHARGE_ID

END
END
