           ,[FINANCE_END_MONTH]
           ,[YEAR_CODE]
           ,[DEFAULT_CURRENCY_ID]
           ,[TIMEZONE]
           ,[NO_OF_USER]
           ,[WEBSITE]
           ,[COMP_BIG_LOGO]
           ,[COMP_SMALL_LOGO]
           ,[COMP_LETTER_HEAD]
           ,[COMP_STAMP_LOGO]
           ,[REMARKS]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[CREATED_MAC_ADDRESS]
