)
VALUES
(
 @FIELD_ID_FLD_DTL
,@ACTIVITY_NAME_FLD_DTL
,@ACTIVITY_DESC_FLD_DTL
,@STATUS_FLD_DTL
,@REMARKS_FLD_DTL
,@USER
