GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [VMaster].[SAVE_LINKS_AND_PAGES]
(
@LINK_ID	int	,
@SUB_MENU_ID	int	,
@LINK_NAME	varchar(100)	,
@PAGE_ACTION	varchar(100)	,
@REDIRECTION_TYPE	varchar(100)	,
@LINK_LOCATION	varchar(100)	,
@LINK_SEQ_ID	int	,
@STYLE_CSS	varchar(1000)	,
@STATUS_MASTER	varchar(20)	,
@USER	varchar(50)	 
)
AS BEGIN SET NOCOUNT ON
BEGIN try
begin transaction


 INSERT INTO [vmaster].[TBL_LINKS_AND_PAGES]
           ([SUB_MENU_ID]
           ,[LINK_NAME]
           ,[PAGE_ACTION]
           ,[REDIRECTION_TYPE]
           ,[LINK_LOCATION]
           ,[LINK_SEQ_ID]
           ,[STYLE_CSS]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE])
     VALUES
           (@SUB_MENU_ID
           ,@LINK_NAME
           ,@PAGE_ACTION
           ,@REDIRECTION_TYPE
           ,@LINK_LOCATION
           ,@LINK_SEQ_ID
           ,@STYLE_CSS 
           ,@STATUS_MASTER 
           ,@USER
           ,GETDATE()
           ,@USER
           ,GETDATE ())
SELECT 'error','DATA SAVED SUCCESSFULLY',@LINK_ID 


commit transaction
end try
begin catch
declare @msg varchar(max)=''
 set @msg = 'ERROR: ' + ERROR_MESSAGE() + ' at ' 
            + coalesce(ERROR_PROCEDURE(), '')
            + coalesce (' line:' + convert(varchar(30), ERROR_LINE()), '')
 rollback tran
 RAISERROR (@msg, 0, 1) with nowait -- ensure the message gets out
end catch
END
GO
