CREATE PROCEDURE [VMaster].[SAVE_PRICE_LIST_MASTER]
(
    @PRICE_LIST_ID INT,
    @PRICE_TYPE_ID INT,
    @COMPANY_ID INT,
    @PRICE_PACKAGE_ID INT,
    @PER_DAY_OR_TRIP_OR_QTY_PRICE DECIMAL(15,2),
    @FOOD_LIMIT_AMOUNT DECIMAL(15,2),
    @DRINKS_LIMIT_AMOUNT DECIMAL(15,2),
    @ACCOMDATION_LIMIT_AMOUNT DECIMAL(15,2),
    @CURRENCY_ID INT,
    @EFFECTIVE_FROM DATETIME,
    @EFFECTIVE_TO DATETIME,
    @REQUESTED_BY VARCHAR(50),
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 'CHECK'
        FROM [VMaster].[TBL_PRICE_LIST_MASTER]
        WHERE  
          COMPANY_ID=@COMPANY_ID  AND PRICE_TYPE_ID=@PRICE_TYPE_ID
    )
    BEGIN
        SELECT 'error','Price List Already Exists',''
    END

	ELSE BEGIN
    INSERT INTO [VMaster].[TBL_PRICE_LIST_MASTER]
    (
        PRICE_TYPE_ID,
         
        COMPANY_ID,
        PRICE_PACKAGE_ID,
        PER_DAY_OR_TRIP_OR_QTY_PRICE,
        FOOD_LIMIT_AMOUNT,
        DRINKS_LIMIT_AMOUNT,
        ACCOMDATION_LIMIT_AMOUNT,
        CURRENCY_ID,
        EFFECTIVE_FROM,
        EFFECTIVE_TO,
        REQUESTED_BY,
        REQUESTED_DATE,
        REMARKS,
        STATUS_MASTER,
        CREATED_BY,
        CREATED_DATE,
        CREATED_MAC_ADDRESS,
        MODIFIED_BY,
        MODIFIED_DATE,
        MODIFIED_MAC_ADDRESS
    )
    VALUES
    (
        @PRICE_TYPE_ID,
        @COMPANY_ID,
        @PRICE_PACKAGE_ID,
        @PER_DAY_OR_TRIP_OR_QTY_PRICE,
        @FOOD_LIMIT_AMOUNT,
        @DRINKS_LIMIT_AMOUNT,
        @ACCOMDATION_LIMIT_AMOUNT,
        @CURRENCY_ID,
        @EFFECTIVE_FROM,
        @EFFECTIVE_TO,
        @REQUESTED_BY,
        GETDATE(),
        @REMARKS,
        @STATUS_MASTER,
        @USER,
        GETDATE(),
        @MAC_ADDRESS,
        @USER,
        GETDATE(),
        @MAC_ADDRESS
    )


    SELECT '', 'Data Saved Successfully',@PRICE_LIST_ID 
END
END
 
GO
