/****** Object:  StoredProcedure [VMaster].[SAVE_SUB_MENU]    Script Date: 23 Jul 2026 18:22:39 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [VMaster].[SAVE_SUB_MENU]
(
@SUB_MENU_ID	int	,
@MAIN_MENU_ID	int	,
@SUB_MENU_NAME	varchar(100)	,
@SUB_MENU_LOCATION	varchar(100)	,
@SUB_MENU_SEQ_ID	int	,
@STYLE_CSS	varchar(1000)	,
@PAGE_ACTION	varchar(100)	,
@IS_PARENT	varchar(25)	,
@STATUS_MASTER	varchar(20)	,
@USER	varchar(50)	 
)
AS BEGIN SET NOCOUNT ON
BEGIN try
begin transaction
IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_SUB_MENU] R WHERE SUB_MENU_NAME=@SUB_MENU_NAME    AND MAIN_MENU_ID=@MAIN_MENU_ID)
BEGIN
    SELECT 'error','SUB MENU NAME ALREADY EXISTS','0'
END

ELSE BEGIN
INSERT INTO [vmaster].[TBL_SUB_MENU]
           ([MAIN_MENU_ID]
           ,[SUB_MENU_NAME]
           ,[SUB_MENU_LOCATION]
           ,[SUB_MENU_SEQ_ID]
           ,[STYLE_CSS]
           ,[PAGE_ACTION]
           ,[IS_PARENT]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE])
     VALUES
           (@MAIN_MENU_ID
           ,@SUB_MENU_NAME
           ,@SUB_MENU_LOCATION
           ,@SUB_MENU_SEQ_ID
           ,@STYLE_CSS 
           ,@PAGE_ACTION
           ,@IS_PARENT 
           ,@STATUS_MASTER 
           ,@USER
           ,GETDATE()
           ,@USER
           ,GETDATE ())
 SELECT '','DATA SAVED SUCCESSFULLY',@SUB_MENU_ID 
 END

commit transaction
end try
begin catch
declare @msg varchar(max)=''
 set @msg = 'ERROR: ' + ERROR_MESSAGE() + ' at ' 
            + coalesce(ERROR_PROCEDURE(), '')
            + coalesce (' line:' + convert(varchar(30), ERROR_LINE()), '')
 rollback tran
 RAISERROR (@msg, 0, 1) with nowait -- ensure the message gets out
end catch
END
GO
