GO


CREATE PROCEDURE [VMaster].[SHOW_ANIMAL_HUNTING_CHARGES_MASTER_DTL]
(@ANIMAL_HUNT_CHARGE_ID INT)
AS
BEGIN
SET NOCOUNT ON

SELECT
	SNO,	 
	ANIMAL_NAME,
    REPLACE(CONVERT(VARCHAR(50),GOVT_RATE,106),' ','-') GOVT_RATE, 
	ACTUAL_AMOUNT,
	A.REMARKS,
	Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_DTL] A
LEFT JOIN  VMaster.TBL_ANIMAL_MASTER AS  N ON  A.ANIMAL_ID =N.ANIMAL_ID 
WHERE A.STATUS_MASTER ='AC' AND ANIMAL_HUNT_CHARGE_ID=@ANIMAL_HUNT_CHARGE_ID

END
GO
/****** Object:  StoredProcedure [VMaster].[SHOW_ANIMAL_HUNTING_CHARGES_MASTER_HDR]    Script Date: 23 Jul 2026 18:22:39 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [VMaster].[SHOW_ANIMAL_HUNTING_CHARGES_MASTER_HDR]
(@ANIMAL_HUNT_CHARGE_ID INT)
AS
BEGIN
SET NOCOUNT ON

SELECT
	ANIMAL_HUNT_CHARGE_ID,
	COMPANY_NAME,
	EFFECTIVE_YEAR,
	ISSUING_AUTHORITY,
	APPROVAL_REFERENCE_NO,
	REPLACE(CONVERT(VARCHAR(50),APPROVAL_DATE,106),' ','-') APPROVAL_DATE,
	REPLACE(CONVERT(VARCHAR(50),EFFECTIVE_FROM,106),' ','-') EFFECTIVE_FROM, 
	REPLACE(CONVERT(VARCHAR(50),EFFECTIVE_TO,106),' ','-') EFFECTIVE_TO, 
	CURRENCY_NAME,
	A.REMARKS,
	       Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR] AS A
LEFT JOIN  VMASTER.TBL_CURRENCY_MASTER AS  C ON C.CURRENCY_ID =A.CURRENCY_ID 
LEFT JOIN  VMASTER.TBL_COMPANY_MASTER AS   CA ON CA.COMPANY_ID =A.COMPANY_ID 
WHERE A.STATUS_MASTER ='AC' AND  ANIMAL_HUNT_CHARGE_ID=@ANIMAL_HUNT_CHARGE_ID

END
