CREATE PROCEDURE [VMaster].[SHOW_BULLET_MASTER]
(
@AMMUNITION_BRAND_ID VARCHAR(50),
@CALIBER_ID VARCHAR(50)
)
AS 
BEGIN

SET NOCOUNT ON

SELECT
       A.[BULLET_ID]
      ,A.[BULLET_CODE]
      ,A.[BULLET_NAME]
      ,BRAND_NAME 
      ,[CALIBER_NAME]
      ,[GRAIN_WEIGHT]
      ,[PACK_SIZE]
      ,[ROUNDS_PER_BOX]
      ,[REORDER_LEVEL]
      ,A.[REMARKS]
      ,Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER]
FROM [VMaster].[TBL_BULLET_Master] AS A
LEFT JOIN   VMASTER.TBL_BULLET_TYPE_Master  AS B ON  A.BULLET_TYPE_ID=B.BULLET_TYPE_ID
LEFT JOIN   VMASTER.TBL_AMMUNITION_BRAND_Master  AS C ON  C.AMMUNITION_BRAND_ID =A.AMMUNITION_BRAND_ID 
LEFT JOIN   VMaster.TBL_CALIBER_Master  AS   D ON D.CALIBER_ID = A.CALIBER_ID 
WHERE  A.STATUS_MASTER ='AC'
AND 
CASE when @AMMUNITION_BRAND_ID  <>'' and @AMMUNITION_BRAND_ID <>'0' then
charindex(',' +convert(varchar(max),a.AMMUNITION_BRAND_ID  ) +',',','+@AMMUNITION_BRAND_ID +',') else 1 end >0  
AND 
CASE when @CALIBER_ID  <>'' and @CALIBER_ID <>'0' then
charindex(',' +convert(varchar(max),a.CALIBER_ID  ) +',',','+@CALIBER_ID +',') else 1 end >0   






END


 
GO
