/****** Object:  StoredProcedure [VMaster].[SHOW_GUN_MASTER]    Script Date: 23 Jul 2026 18:22:39 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [VMaster].[SHOW_GUN_MASTER]
(
    @GUN_CATEGORY_ID VARCHAR(50),
    @GUN_TYPE_ID VARCHAR(50),
    @GUN_BRAND_ID VARCHAR(50),
    @CALIBER_ID VARCHAR(50),
    @CAMP_ID VARCHAR(50),
    @STORE_ID VARCHAR(50)
)
AS 
BEGIN

SET NOCOUNT ON

SELECT 
       [GUN_ID],
       [GUN_CODE],
       [GUN_NAME],
       GUN_CATEGORY_NAME,
       c.TYPE_NAME,
       [BRAND_Name],
       [CALIBER_NAME] ,
       CA.CAMP_NAME ,
       [STORE_name],
       [MODEL],
       [SERIAL_NUMBER],
       [BARREL_LENGTH],
       [MAGAZINE_CAPACITY],
       [LICENSE_NUMBER],
       a.[REMARKS],
       Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER]
FROM [VMaster].[TBL_GUN_MASTER] AS A
left join  vmaster.TBL_GUN_CATEGORY_Master as b on  a.GUN_CATEGORY_ID =b.GUN_CATEGORY_ID 
left join  vmaster.TBL_GUN_TYPE_Master as c on  a.GUN_TYPE_ID =c.GUN_TYPE_ID 
left join  vmaster.TBL_GUN_BRAND_MASTER as d on  a.GUN_BRAND_ID =d.GUN_BRAND_ID 
left join  vmaster.TBL_CALIBER_Master  as e on  a.CALIBER_ID =e.CALIBER_ID 
left join  vmaster.tbl_Store_Master  as s on  a.STORE_ID =s.STORE_ID 
left join  vmaster.TBL_CAMP_MASTER  as CA on  a.CAMP_ID  =CA.CAMP_ID 
WHERE A.STATUS_MASTER = 'AC'
 

AND 
CASE WHEN @GUN_CATEGORY_ID <> '' AND @GUN_CATEGORY_ID <> '0' THEN
CHARINDEX(',' + CONVERT(VARCHAR(MAX),A.GUN_CATEGORY_ID) + ',', ',' + @GUN_CATEGORY_ID + ',')
ELSE 1 END > 0

AND 
CASE WHEN @GUN_TYPE_ID <> '' AND @GUN_TYPE_ID <> '0' THEN
CHARINDEX(',' + CONVERT(VARCHAR(MAX),A.GUN_TYPE_ID) + ',', ',' + @GUN_TYPE_ID + ',')
ELSE 1 END > 0

AND 
CASE WHEN @GUN_BRAND_ID <> '' AND @GUN_BRAND_ID <> '0' THEN
CHARINDEX(',' + CONVERT(VARCHAR(MAX),A.GUN_BRAND_ID) + ',', ',' + @GUN_BRAND_ID + ',')
ELSE 1 END > 0

AND 
CASE WHEN @CALIBER_ID <> '' AND @CALIBER_ID <> '0' THEN
CHARINDEX(',' + CONVERT(VARCHAR(MAX),A.CALIBER_ID) + ',', ',' + @CALIBER_ID + ',')
ELSE 1 END > 0

AND 
CASE WHEN @CAMP_ID <> '' AND @CAMP_ID <> '0' THEN
CHARINDEX(',' + CONVERT(VARCHAR(MAX),A.CAMP_ID) + ',', ',' + @CAMP_ID + ',')
ELSE 1 END > 0

AND 
CASE WHEN @STORE_ID <> '' AND @STORE_ID <> '0' THEN
CHARINDEX(',' + CONVERT(VARCHAR(MAX),A.STORE_ID) + ',', ',' + @STORE_ID + ',')
ELSE 1 END > 0

END
 

 
GO
