CREATE PROCEDURE [VMaster].[SHOW_PRODUCT_COMPANY_MAIN_CATEGORY_MAPPING]
(
@COMPANY_ID VARCHAR(50),
@MAIN_CATEGORY_ID VARCHAR(5)
)
AS 
BEGIN

SET NOCOUNT ON

SELECT [SNO]
      ,[COMPANY_NAME]
      ,[MAIN_CATEGORY_NAME]
      ,A.[REMARKS]
      ,Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
FROM [VMaster].[TBL_PRODUCT_COMPANY_MAIN_CATEGORY_MAPPING] AS A
LEFT JOIN   VMaster.TBL_PRODUCT_MAIN_CATEGORY_MASTER AS  B ON  B.MAIN_CATEGORY_ID =A.MAIN_CATEGORY_ID 
LEFT JOIN  VMASTER.TBL_COMPANY_MASTER AS  CA ON CA.COMPANY_ID =A.COMPANY_ID 
WHERE  A.STATUS_MASTER ='AC' AND 
	CASE when @MAIN_CATEGORY_ID  <>'' and @MAIN_CATEGORY_ID <>'0' then
	charindex(',' +convert(varchar(max),a.MAIN_CATEGORY_ID  ) +',',','+@MAIN_CATEGORY_ID +',') else 1 end >0  
 AND 		CASE when @COMPANY_ID  <>'' and @COMPANY_ID <>'0' then
	charindex(',' +convert(varchar(max),a.COMPANY_ID  ) +',',','+@COMPANY_ID +',') else 1 end >0  

END

