CREATE PROCEDURE [VMaster].[Show_Role_to_Link_Pages]
(
	@role_id varchar(50),
	@link_id varchar(50)
)
as
begin
set nocount on

SELECT A.ROLE_TO_LINK_ID_ROLE_TO_LINK'Ref Id',b.ROLE_NAME,l.LINK_NAME,a.STATUS_ROLE_TO_LINK'Status',a.CREATED_USER_ROLE_TO_LINK'Created By',a.CREATED_DATE_ROLE_TO_LINK'Created Date' 
from vmaster.TBL_ROLE_TO_LINK_AND_PAGE as a
inner join vmaster.TBL_ROLE_master as b on a.ROLE_ID_ROLE_TO_LINK=b.ROLE_ID
inner join vmaster.TBL_LINKS_AND_PAGES as l on l.LINK_ID=a.LINK_ID_ROLE_TO_LINK
where 
--	 case when @role_id<>'' and @role_id<>'0' then
--		charindex(',' + a.ROLE_ID_TO_LINK+',',','+@role_id+',') else 1 end >0 

--and	 case when @link_id<>'' and @link_id<>'0' then
--		charindex(',' + a.LINK_ID_ROLE_TO_LINK+',',','+@link_id+',') else 1 end >0 

	case when @role_id<>'' and @role_id<>'0' then
		charindex(',' + CAST(ROLE_ID AS VARCHAR(100))+',',','+@role_id+',') else 1 end >0 
	and case when @LINK_ID<>'' and @LINK_ID<>'0' then
		charindex(',' + CAST(LINK_ID AS VARCHAR(100))+',',','+@LINK_ID+',') else 1 end >0 

end
