--select * from [vmaster].[TBL_ROLE_MASTER]
CREATE PROCEDURE [VMaster].[SHOW_TO_LINK_AND_PAGE]
(
@ROLE_TO_LINK_ID_ROLE_TO_LINK int,
@LINK_ID_ROLE_TO_LINK INT
)
AS BEGIN SET NOCOUNT ON
  SELECT [ROLE_TO_LINK_ID_ROLE_TO_LINK]
      ,B.ROLE_NAME  
      ,C.LINK_NAME 
      ,[STATUS_ROLE_TO_LINK]
  FROM [vmaster].[TBL_ROLE_TO_LINK_AND_PAGE] AS A
  INNER JOIN [vmaster].[TBL_ROLE_MASTER] AS B ON A.ROLE_ID_ROLE_TO_LINK =B.ROLE_ID 
INNER JOIN [vmaster].[TBL_LINKS_AND_PAGES] AS C ON A.LINK_ID_ROLE_TO_LINK =C.LINK_ID  
WHERE A.ROLE_TO_LINK_ID_ROLE_TO_LINK=@ROLE_TO_LINK_ID_ROLE_TO_LINK AND

CASE WHEN @LINK_ID_ROLE_TO_LINK   <>'' AND @LINK_ID_ROLE_TO_LINK  <>'' AND @LINK_ID_ROLE_TO_LINK  >'0' THEN 
CHARINDEX(','+LTRIM(RTRIM(LINK_ID_ROLE_TO_LINK  ))+',',','+@LINK_ID_ROLE_TO_LINK  +',') ELSE 1 END >0

END
 --select * FROM [vmaster].[TBL_ROLE_TO_LINK_AND_PAGE]
 --select * FROM [vmaster].[TBL_ROLE_TO_LINK_AND_PAGE]
