	@ANIMAL_HUNT_CHARGE_ID INT,
	@ANIMAL_ID INT,
	@GOVT_RATE DECIMAL(15,2),
	@ACTUAL_AMOUNT DECIMAL(15,2),
	@REMARKS VARCHAR(1000),
	@STATUS_MASTER VARCHAR(20),
	@USER VARCHAR(50),
	@MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
SET NOCOUNT ON

IF EXISTS
(
	SELECT 'X'
	FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_DTL]
	WHERE ANIMAL_HUNT_CHARGE_ID=@ANIMAL_HUNT_CHARGE_ID
	AND ANIMAL_ID=@ANIMAL_ID
	AND SNO<>@SNO
)
BEGIN
	SELECT 'error','ANIMAL ALREADY EXISTS FOR THIS HUNTING CHARGE','0'
END
ELSE
BEGIN

UPDATE [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_DTL]
SET
	ANIMAL_HUNT_CHARGE_ID=@ANIMAL_HUNT_CHARGE_ID,
	ANIMAL_ID=@ANIMAL_ID,
