	ACTUAL_AMOUNT=@ACTUAL_AMOUNT,
	REMARKS=@REMARKS,
	STATUS_MASTER=@STATUS_MASTER,
	MODIFIED_BY=@USER,
	MODIFIED_DATE=GETDATE(),
	MODIFIED_MAC_ADDRESS=@MAC_ADDRESS
WHERE SNO=@SNO

SELECT '','RECORD UPDATED SUCCESSFULL',@SNO

END
END
