CREATE PROCEDURE [VMaster].[UPDATE_FIELD_DTL]
(
	@ACTIVITY_ID_FLD_DTL BIGINT,
	@FIELD_ID_FLD_DTL BIGINT,
	@ACTIVITY_NAME_FLD_DTL VARCHAR(MAX),
	@ACTIVITY_DESC_FLD_DTL VARCHAR(MAX),
	@STATUS_FLD_DTL VARCHAR(10),
	@REMARKS_FLD_DTL VARCHAR(1000),
	@USER VARCHAR(50),
	@MAC_ADDRESS VARCHAR(50)
)

AS
BEGIN

SET NOCOUNT ON


IF NOT EXISTS
(
	SELECT 'X'
	FROM [VMaster].[TBL_FIELD_HDR]
	WHERE FIELD_ID_FLD_HDR=@FIELD_ID_FLD_DTL
)
BEGIN
	SELECT 'Error','FIELD RECORD NOT EXISTS','0'
END

ELSE IF EXISTS
(
	SELECT 'X'
	FROM [VMaster].[TBL_FIELD_DTL]
	WHERE ACTIVITY_NAME_FLD_DTL=@ACTIVITY_NAME_FLD_DTL
	AND FIELD_ID_FLD_DTL=@FIELD_ID_FLD_DTL
	AND ACTIVITY_ID_FLD_DTL<>@ACTIVITY_ID_FLD_DTL
)

BEGIN
	SELECT 'error','ACTIVITY NAME ALREADY EXISTS','0'
END

ELSE
BEGIN

UPDATE [VMaster].[TBL_FIELD_DTL]

SET
 [FIELD_ID_FLD_DTL]=@FIELD_ID_FLD_DTL
,[ACTIVITY_NAME_FLD_DTL]=@ACTIVITY_NAME_FLD_DTL
,[ACTIVITY_DESC_FLD_DTL]=@ACTIVITY_DESC_FLD_DTL
