    @LICENSE_PERMIT_NAME VARCHAR(50),
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON
	IF EXISTS(SELECT 'CHECK' FROM [VMaster].[TBL_LICENSE_PERMIT_TYPE_MASTER]     WHERE UPPER(LICENSE_PERMIT_NAME) = UPPER(@LICENSE_PERMIT_NAME)        AND LICENSE_PERMIT_ID <> @LICENSE_PERMIT_ID    )
    BEGIN
