        REMARKS = @REMARKS,
        STATUS_MASTER = @STATUS_MASTER,
        MODIFIED_BY = @USER,
        MODIFIED_DATE = GETDATE(),
        MODIFIED_MAC_ADDRESS = @MAC_ADDRESS
    WHERE LICENSE_PERMIT_ID = @LICENSE_PERMIT_ID;


    SELECT '', 'Record Updated Successfully', @LICENSE_PERMIT_ID


	END
END
 

