CREATE PROCEDURE [VMaster].[UPDATE_LINKS_AND_PAGES]
(
@LINK_ID	int	,
@SUB_MENU_ID	int	,
@LINK_NAME	varchar(100)	,
@PAGE_ACTION	varchar(100)	,
@REDIRECTION_TYPE	varchar(100)	,
@LINK_LOCATION	varchar(100)	,
@LINK_SEQ_ID	int	,
@STYLE_CSS	varchar(1000)	,
@STATUS_MASTER	varchar(20)	,
@USER	varchar(50)	 
)
AS BEGIN SET NOCOUNT ON
 


IF NOT EXISTS(SELECT 'X' FROM [VMaster].[TBL_LINKS_AND_PAGES] WHERE LINK_ID=@LINK_ID)
BEGIN
    SELECT 'ERROR','RECORD NOT EXISTS',@LINK_ID
END


-- CHECK DUPLICATE LINK NAME
IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_LINKS_AND_PAGES]     WHERE LINK_NAME=@LINK_NAME    AND SUB_MENU_ID=@SUB_MENU_ID   AND LINK_ID<>@LINK_ID)
BEGIN
    SELECT 'ERROR','LINK NAME ALREADY EXISTS',@LINK_ID 
END

ELSE BEGIN

 UPDATE [vmaster].[TBL_LINKS_AND_PAGES]
   SET [SUB_MENU_ID] = @SUB_MENU_ID 
      ,[LINK_NAME] = @LINK_NAME
      ,[PAGE_ACTION] = @PAGE_ACTION
      ,[REDIRECTION_TYPE] = @REDIRECTION_TYPE
      ,[LINK_LOCATION] = @LINK_LOCATION
      ,[LINK_SEQ_ID] = @LINK_SEQ_ID 
      ,[STYLE_CSS] = @STYLE_CSS 
      ,[STATUS_MASTER] = @STATUS_MASTER 
      ,[MODIFIED_BY] = @USER
      ,[MODIFIED_DATE] = GETDATE ()
 WHERE LINK_ID=@LINK_ID 
SELECT '','RECORD UPDATED SUCCESSFULLY',@LINK_ID


 
END
END
