/****** Object:  StoredProcedure [VMaster].[UPDATE_MAIN_MENU]    Script Date: 23 Jul 2026 18:22:39 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [VMaster].[UPDATE_MAIN_MENU]
(
@MAIN_MENU_ID	int	,
@MAIN_MENU_NAME	varchar(100),
@MAIN_MENU_LOCATION	varchar(100),
@MAIN_MENU_SEQ_ID	int,
@STATUS_MASTER	varchar(20),
@STYLE_CSS	varchar(1000)	,
@PAGE_ACTION	varchar(100)	,
@USER	varchar(50 )
 

)
AS BEGIN SET NOCOUNT ON 
BEGIN try
begin transaction

IF NOT EXISTS(SELECT 'X' FROM [VMaster].[TBL_MAIN_MENU] WHERE MAIN_MENU_ID=@MAIN_MENU_ID)
BEGIN
    SELECT 'Error','RECORD NOT EXISTS',@MAIN_MENU_ID
END

ELSE IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_MAIN_MENU] R WHERE MAIN_MENU_NAME=@MAIN_MENU_NAME     AND MAIN_MENU_ID <> @MAIN_MENU_ID)
BEGIN
    SELECT 'error','MAIN MENU NAME ALREADY EXISTS','0'
END

ELSE BEGIN
 UPDATE [vmaster].[TBL_MAIN_MENU]
   SET [MAIN_MENU_NAME] = @MAIN_MENU_NAME
      ,[MAIN_MENU_LOCATION] = @MAIN_MENU_LOCATION
      ,[MAIN_MENU_SEQ_ID] = @MAIN_MENU_SEQ_ID 
      ,[STATUS_MASTER] = @STATUS_MASTER 
      ,[STYLE_CSS] = @STYLE_CSS 
      ,[PAGE_ACTION] = @PAGE_ACTION
      
      ,[MODIFIED_BY] = @USER 
      ,[MODIFIED_DATE] = GETDATE ()
 WHERE MAIN_MENU_ID=@MAIN_MENU_ID 
SELECT '','DATA UPDATED SUCCESSFULLY',@MAIN_MENU_ID 

END


commit transaction
end try
begin catch
declare @msg varchar(max)=''
 set @msg = 'ERROR: ' + ERROR_MESSAGE() + ' at ' 
            + coalesce(ERROR_PROCEDURE(), '')
            + coalesce (' line:' + convert(varchar(30), ERROR_LINE()), '')
 rollback tran
 RAISERROR (@msg, 0, 1) with nowait -- ensure the message gets out
end catch

END
GO
