@SUB_MENU_NAME	varchar(100)	,
@SUB_MENU_LOCATION	varchar(100)	,
@SUB_MENU_SEQ_ID	int	,
@STYLE_CSS	varchar(1000)	,
@PAGE_ACTION	varchar(100)	,
@IS_PARENT	varchar(25)	,
@STATUS_MASTER	varchar(20)	,
@USER	varchar(50)	 
)
AS BEGIN SET NOCOUNT ON
 BEGIN try
begin transaction

IF NOT EXISTS(SELECT 'X' FROM [VMaster].[TBL_SUB_MENU] WHERE SUB_MENU_ID=@SUB_MENU_ID)
BEGIN
    SELECT 'Error','RECORD NOT EXISTS',@SUB_MENU_ID
END

ELSE IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_SUB_MENU] R WHERE SUB_MENU_NAME=@SUB_MENU_NAME    AND MAIN_MENU_ID=@MAIN_MENU_ID AND SUB_MENU_ID <> @SUB_MENU_ID)
BEGIN
    SELECT '','SUB MENU NAME ALREADY EXISTS','0'
END


ELSE BEGIN

UPDATE [vmaster].[TBL_SUB_MENU]
   SET [MAIN_MENU_ID] = @MAIN_MENU_ID
      ,[SUB_MENU_NAME] = @SUB_MENU_NAME 
      ,[SUB_MENU_LOCATION] = @SUB_MENU_LOCATION 
      ,[SUB_MENU_SEQ_ID] = @SUB_MENU_SEQ_ID
      ,[STYLE_CSS] = @STYLE_CSS
      ,[PAGE_ACTION] = @PAGE_ACTION 
      ,[IS_PARENT] = @IS_PARENT 
      ,[STATUS_MASTER] = @STATUS_MASTER 
     
      ,[MODIFIED_BY] = @USER
      ,[MODIFIED_DATE] = GETDATE ()
 WHERE SUB_MENU_ID=@SUB_MENU_ID  
 SELECT '','RECORD UPDATED SUCCESSFULLY',@SUB_MENU_ID 
 
 END

commit transaction
end try
begin catch
declare @msg varchar(max)=''
 set @msg = 'ERROR: ' + ERROR_MESSAGE() + ' at ' 
            + coalesce(ERROR_PROCEDURE(), '')
            + coalesce (' line:' + convert(varchar(30), ERROR_LINE()), '')
 rollback tran
 RAISERROR (@msg, 0, 1) with nowait -- ensure the message gets out
end catch
END
GO
